/* IDO 7.1 NCC (C++) EXACT donor for gl_func_0003BE1C (0x620 / 392 words), agent-c run 178 lift, agent-g run 325 exact
 * (spliced over a placeholder on both build paths; the residual notes below are history).
 * Real C++ `int Obj::query(int max, f32 *dist, Tri **out, V3 p)` (vertical ray / ground query, sibling of
 * 3B2EC Obj::height and 3B9C0), ported from the run-110..152 cfe body (77.27): the grid lookup through the
 * same inline Obj members toCell(const V3 &, int &, int &) / cellOf() / list() as 3B2EC (the cell-index
 * homes and per-statement self->col reloads come for free), the K triple through its own symbol
 * D_3BE1C_128 (held base, as the target), off computed BEFORE the grp test, the material callback through a
 * `Col *cc` copy of self->col (off then spills around the call like the target), the 0x100 test as a nested
 * block instead of `continue` (no duplicated loop test), t->a / t->b read before the 0x200 branch, and the
 * edge walk as the cfe do-while with `fv++` inside the condition and the table read `*nx` then `nx++` as
 * its own statement (`*nx++` reads through a copy of the old pointer that takes an s-register); self->col
 * read once into a function-scope `Col *cc` (the target's s1) and re-read into it per triangle; the
 * single-use locals ia / ib / ic, vt, qa / qb and sg DE-NAMED (macros: each named scalar costs an NCC home
 * and a colour; de-naming them took the frame to the target's 0xF0 with s0..s7 only, 83.38 -> 87.55).
 * The face() argument written as an rvalue (`i + 0`; `i | 0` is the same, a plain `i` or a named copy is
 * not): edg then passes it through a parameter temp and the expansion's `this` copy lands in the target's v0
 * (87.55 -> 88.59). cfe 77.27 -> 88.59 local, 1560 bytes (target 1568, cfe 1528). Residual: the face pointer
 * is not copied into s0 after the face() expansion, off spills to sp+76 (target sp+84), r is not copied into a0, the first
 * inner MAX is evaluated as two arms (the target pre-assigns one before the branch) and the edge-loop
 * schedule. agent-c run 193 (decode): the edge loop computes dx / dy (qa / qb minus the first vertex) BEFORE
 * ex / ey: the target loads v0[a] and v0[b] together and converts both before the v1[] reads; the loop block
 * now aligns word-for-word (up to colours): 88.59 -> 94.9 local, 1560 -> 1552 bytes (target 1568: away,
 * flagged; the deficit is the missing face / r copies and the two-arm inner MAX listed above).
 * agent-c run 194: face() called on the member `col` (plain `i`), `cc = col` after it: 94.93 -> 95.40 local,
 * 1552 -> 1556 bytes (toward 1568).
 * agent-c run 249 (98.56 -> 98.62, frame 0xF0 = target, q / cx / cz homes at the target's frame offsets): the
 * loop locals declared at function scope BEFORE cx / cz (q after off / f / ok / t / n), toCell written out in
 * cellOf and face() without its `r` local (3 + 1 inline homes fewer); keeping `r` block-scope matters (off + f + r
 * hoisted together moves the loop's -1 constant).
 * agent-g run 325: EXACT (alias in va + edge-loop split + v0[a] test, see the loop). */
typedef signed char s8; typedef unsigned char u8; typedef short s16; typedef unsigned short u16;
typedef int s32; typedef unsigned int u32; typedef float f32;
extern "C" {
extern char D_00000000[];
int gl_func_00000000(...);
extern s16 D_3BE1C_c[];
extern f32 D_3BE1C_128[];
}
#define K(o) (*(f32 *)(D_00000000 + (o)))
struct V3 { f32 x, y, z; };
struct Tri { s8 a, b, ax, sgn; s16 grp, pad6; f32 d; };
struct Face { u16 mat; u16 vi[3]; };
struct Grid {
    int w, h, x0, z0; f32 cw, ch; s16 *lists; int *cells;
};
struct Col {
    char pad0[0x4C]; s16 *remap; char pad50[4]; V3 *nrm; char pad58[8]; s16 (*verts)[3];
    char pad64[4]; Face *faces; char pad6c[0x34]; Grid *grid;
    Face *face(int i) { return remap ? &faces[remap[i]] : &faces[i]; }
};
#define MAXS(a, b) ((a) > (b) ? (s16)(a) : (s16)(b))
#define MINS(a, b) ((a) < (b) ? (s16)(a) : (s16)(b))
struct Obj {
    char pad0[0x2C]; Tri *tris; char pad30[0x54]; Col *col;
    int query(int max, f32 *dist, Tri **out, V3 p);
    void toCell(const V3 &p, int &cx, int &cz) {
        cx = (p.x - col->grid->x0) / col->grid->cw;
        cz = (p.z - col->grid->z0) / col->grid->ch;
    }
    int cellOf(const V3 &p, int &cx, int &cz) { /* agent-g run 238: cx / cz are query()'s locals (98.34 -> 98.51) */
        cx = (p.x - col->grid->x0) / col->grid->cw;
        cz = (p.z - col->grid->z0) / col->grid->ch;
        if (cx >= 0 && cx < col->grid->w && cz >= 0 && cz < col->grid->h) return cx + cz * col->grid->w; /* agent-g run 231: cx first (operand-commute sweep), 97.60 -> 98.16 */
        return -1;
    }
    s16 *list(int cell) { return col->grid->cells[cell] != -1 ? &col->grid->lists[col->grid->cells[cell]] : 0; }
};

int Obj::query(int max, f32 *dist, Tri **out, V3 p) {
    Col *cc;
    int cnt;
    int cell;
    s16 *list;
    int i;
    int off;
    Face *f;
    int ok;
    Tri *t;
    V3 *n;
    f32 q[3];
    int a;
    int b;
    s16 *va;
    s16 *vb;
    s16 *vc;
    int k;
    s16 hi;
    s16 lo;
    s16 *nx;
    u16 *fv;
    s16 *v0;
    s16 *v1;
    s16 dx;
    s16 dy;
    s16 ex;
    s16 ey;
    int cx, cz;
    cc = col;
    cnt = 0;
    if (cc == 0) return 0;
    if (cc->grid == 0) gl_func_00000000(D_00000000 + 0x1EE9C); /* agent-g run 277: the run-238 folded use of col dropped (inert after the face() change below; kit CCCXXIX prune) */
    p.x *= D_3BE1C_128[0];
    p.y *= D_3BE1C_128[1];
    p.z *= D_3BE1C_128[2];
    cell = cellOf(p, cx, cz);
    if (cell < 0) return 0;
    list = this->list(cell);
    if (list == 0) return 0;
    while ((i = *list++) != -1) {
        off = i * 12; /* agent-g run 266: ugen's multiply-by-constant expansion builds sll / subu / sll in the destination register (target a2 throughout); the shift spelling took a t temp and shifted the t ring */
        if (((Tri *)((char *)tris + off))->grp < 0) continue;
        /* agent-g run 277: cc = col BEFORE the face() expansion and face() called on the rvalue `cc + i * 0`: the
         * col load lands in cc's colour s1 (target `lw s1,132(s5)`, the call argument `or a0,s1`) and the
         * expansion's `this` temp is the v0 copy; on `col->face(i)` the load took t0 (99.11 -> 99.17) */
        cc = col;
        f = (cc + i * 0)->face(i) + 0 * (int)(*list); /* agent-g run 210: fourth pass (list points at the next entry or the -1 terminator): 97.26 -> 97.33, 1564 -> 1568 bytes = target */
        int r = gl_func_00000000(cc, f->mat) | 0 * (int)(cc); /* agent-g run 210: folded counted use (zero-use sweep): 95.48 -> 96.38, 1556 -> 1560 bytes (target 1568); agent-g run 267: `|` not `+` -- the `+ 0` form kept an `addu a0,v0,zero` for the result copy, `| 0` gives the target's `or a0,v0,zero` (98.78 -> 98.94) */
        if (r & 0x100) { /* agent-c run 292: agent-g run 266's folded `+ 0 * (int)(cc)` here dropped -- stale after the t->d fix below (kit CCCXXIX re-test): 98.98 -> 99.268 */
            ok = 1;
            n = (V3 *)((char *)col->nrm + off);
            /* agent-g run 325: the run-195 alias copy `V3 *n_al = n` (colour tie) now rides in va (dead store, va is
             * re-assigned before every read in the 0x200 branch): same colours, and n_al's home is gone, so the off
             * call-save slot sits at M-156 like the target (frame 240 comes from the edge-loop split below) */
            va = (s16 *)n;
            /* agent-c run 292 (kit CCCXXX): t->d read through the plain expression, not the variable t (the first
             * `t = tris + off` assignment dropped): the target computes this address into a ugen temp (`addu t7,t9,a2`;
             * `lwc1 $f6,8(t7)`) and only the SECOND t (for a / b) is t's coloured v1 -- ours had a coloured split
             * piece of t here: 99.166 -> 97.98 (ring phase), then 99.268 with the fold above removed */
            f32 d = p.x * ((V3 *)va)->x + p.y * ((V3 *)va)->y + p.z * ((V3 *)va)->z - ((Tri *)((char *)tris + off))->d;
            q[0] = p.x - ((V3 *)va)->x * d;
            q[1] = p.y - ((V3 *)va)->y * d;
            q[2] = p.z - n->z * d;
            t = (Tri *)((char *)tris + off);
            a = t->a;
            b = t->b;
            if (r & 0x200) {
                va = col->verts[f->vi[0]];
                vb = col->verts[f->vi[1]];
                vc = col->verts[f->vi[2]];
                /* agent-g run 323 (kit CDXV): the target colours k * 2 (v0) BEFORE va / vb (a0 / a1) and ia / ib after
                 * them (a3 / a2). The earlier folded uses (r here, vb / vc / ia on hi, va on ok) kept va / vb live through
                 * the clamp tree, so ia / ib outranked them; instead: no folds there, a dead `if (0) {}` right after k
                 * (k * 2 becomes local to the block after it and wins the 20.0 tie that va took by LR order), one
                 * folded use of va / vb each in k's line (adjsave 10 -> 15) and three `if (1) {}` splitters before lo
                 * (ia 18 -> 15 below va / vb, ib 13.3): 99.778 -> 99.995, same length */
                k = 2 - t->ax | 0 * ((int)va + (int)vb); if (0) { lo = 0; }
#define ia va[k]
#define ib vb[k]
#define ic vc[k]
                hi = MAXS(MAXS(ia, ib), ic);
                if (1) {} if (1) {} if (1) {} lo = MINS(MINS(ia, ib), ic);
                if (q[k] < (f32)lo || (f32)hi < q[k]) ok = 0;
            } else {
#define qa q[a]
#define qb q[b]
#define sg ((f32)t->sgn)
#define vt (col->verts)
                nx = D_3BE1C_c; fv = (u16 *)f; do { /* agent-c run 300: one line (as1 source-line tie: the q[b] lwc1 before nx's addiu %lo, as the target): 99.27 -> 99.78 */
                    v0 = vt[fv[1]];
                    v1 = vt[f->vi[*nx]];
                    nx++;
                    dx = (int)(qa - v0[a]);
                    if (1) {}
                    dy = (int)(qb - v0[b]);
                    ex = v1[a] - v0[a];
                    ey = v1[b] - v0[b];
                    if (v0[a] + v0[a] + v0[a]) {}
                    /* agent-g run 325 (kit CDXVII): the `if (1) {}` after dx splits the loop body (uopt) and ugen's unaccessed
                     * area above the saves grows 20 -> 28 bytes: frame 240 with the off call-save at M-156 (sp+84) as the
                     * target. The split makes v0[b] local to the second half (adjsave 300) and v0[a] span both (200); the
                     * code-free test of v0[a] (three uses in one test at the end of the block, no new block) lifts it to the
                     * tie, which v0[a] wins by LR order (v0 / v1 as the target). The run-231 folds of v1 / v0 on ok dropped. */
                    if (((f32)ex * (f32)dy - (f32)ey * (f32)dx) * sg > 10.0f) ok = 0;
                } while (ok && (fv++, nx < D_3BE1C_c + 3));
            }
            if (ok) {
                dist[cnt] = d / K(0x12C);
                out[cnt] = &tris[i];
                cnt++;
                if (cnt >= max) return cnt;
            }
        }
    }
    return cnt;
}
